def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def step_toward(a, b):
        return clamp_step(b - a)

    def manhattan(p, q):
        return abs(p[0] - q[0]) + abs(p[1] - q[1])

    def first_pair(value):
        if isinstance(value, (list, tuple)) and len(value) >= 2:
            return value[0], value[1]
        return None

    def to_pairs(value):
        out = []
        if isinstance(value, (list, tuple)):
            for item in value:
                p = first_pair(item)
                if p is not None:
                    out.append(p)
        return out

    env = observation.get("environment_name", "resource_collection")
    self_pos = first_pair(observation.get("self_position")) or (0, 0)
    opp_pos = first_pair(observation.get("opponent_position")) or self_pos
    sx, sy = self_pos
    ox, oy = opp_pos
    gw = observation.get("grid_width", 0)
    gh = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            dx = step_toward(sx, ox)
            dy = step_toward(sy, oy)
            if dx == 0 and dy == 0:
                dx = 1 if sx <= ox else -1
            return [dx, dy]
        corners = []
        if gw and gh:
            corners = [(0, 0), (0, gh - 1), (gw - 1, 0), (gw - 1, gh - 1)]
        if corners:
            target = max(corners, key=lambda c: manhattan(c, (ox, oy)))
            return [step_toward(sx, target[0]), step_toward(sy, target[1])]
        return [-step_toward(sx, ox), -step_toward(sy, oy)]

    if env == "territory_control":
        targets = to_pairs(observation.get("unclaimed_cells")) or to_pairs(observation.get("opponent_territory"))
        if not targets:
            targets = to_pairs(observation.get("frontier")) or to_pairs(observation.get("resources"))
        if targets:
            best = min(targets, key=lambda p: (manhattan(p, (sx, sy)), abs(p[0] - ox) + abs(p[1] - oy)))
            dx = step_toward(sx, best[0])
            dy = step_toward(sy, best[1])
            if dx == 0 and dy == 0:
                dx = 1 if sx <= ox else -1
            return [dx, dy]
        return [0, 0]

    resources = to_pairs(observation.get("resources"))
    if resources:
        best = min(resources, key=lambda p: (manhattan(p, (sx, sy)), manhattan(p, (ox, oy))))
        dx = step_toward(sx, best[0])
        dy = step_toward(sy, best[1])
        if dx == 0 and dy == 0:
            dx = step_toward(sx, ox) if (sx, sy) != (ox, oy) else 1
        return [dx, dy]

    dx = step_toward(sx, ox)
    dy = step_toward(sy, oy)
    if dx == 0 and dy == 0:
        return [1, 0]
    return [dx, dy]

